Rules.InvariantScript:
Set(varSelNodeId_L1, ThisItem.NodeId);
Set(varSelectedL1DisplayName, ThisItem.DisplayName);

// Reset niveles inferiores
Set(varSelNodeId_L2, Blank());

Set(varSelectedL2DisplayName, "");

Set(varSelNodeId_L3, Blank());
Set(varSelectedL3DisplayName, "");


Select(btnCfg_RefreshSelectionContext_1);

Set(varSelNodeId_L2, Text(ThisItem.NodeId));

// Reset L3
Set(varSelNodeId_L3, "");
Set(varTargetSubsectionId, "");
Set(varTargetSubsectionName, "");

Select(btnCfg_RefreshSelectionContext_1);

If(
    IsBlank(varSelNodeId_L1),
    Notify("Select a Level 1 header first.", NotificationType.Warning),

    Set(varEditMode, "NEW");
    Set(varEditLevel, 2);
    Set(varEditParentNodeId, Text(varSelNodeId_L1));
    Set(varEditNodeId, "");

    Select(btnNode_OpenModal_1)
);

Set(varSelNodeId_L3, Text(ThisItem.NodeId));
Set(varTargetSubsectionId, Text(ThisItem.NodeId));
Set(varTargetSubsectionName, ThisItem.DisplayName);

// resolver ancestros
With(
    {
        n2: LookUp(
            colNodes,
            Text(NodeId) = Text(ThisItem.ParentNodeId)
        )
    },
    With(
        {
            n1: LookUp(
                colNodes,
                Text(NodeId) = Text(n2.ParentNodeId)
            )
        },
        Set(varSelNodeId_L1, Text(n1.NodeId));
        Set(varSelNodeId_L2, Text(n2.NodeId))
    )
);

// refrescar solo el contexto
Select(btnCfg_RefreshSelectionContext_1);

If(
    IsBlank(varSelNodeId_L2),
    Notify("Select a Level 2 section first.", NotificationType.Warning),

    Set(varEditMode, "NEW");
    Set(varEditLevel, 3);
    Set(varEditParentNodeId, Text(varSelNodeId_L2));
    Set(varEditNodeId, "");

    Select(btnNode_OpenModal_1)
);

Set(varEditNodeId, varSelectedNodeId);

If(
    IsBlank(varEditNodeId),
    Notify("Select a node to edit.", NotificationType.Warning),

    Set(varEditMode, "EDIT");
    Select(btnNode_OpenModal_1)
);

Set(varEditNodeId, varSelectedNodeId);

If(
    IsBlank(varEditNodeId),
    Notify("Select a node to deactivate.", NotificationType.Warning),

    Set(varCfg_IsLoading, true);
    Set(varCfg_Error, "");

    If(
        Text(varEditNodeId) = Text(varSelNodeId_L3),
        Set(varLastSavedNodeId, Text(varSelNodeId_L2)),

        If(
            Text(varEditNodeId) = Text(varSelNodeId_L2),
            Set(varLastSavedNodeId, Text(varSelNodeId_L1)),

            Set(varLastSavedNodeId, "")
        )
    );

    Set(varPendingResolveSavedNode, false);

    IfError(
        WarRoom_ReportConfig_DeactivateNode.Run(
            varProjectId,
            Text(varEditNodeId),
            User().Email
        ),
        Set(varCfg_Error, "Error deactivating node.");
        Notify("Error deactivating node.", NotificationType.Error)
    );

    If(IsBlank(varCfg_Error), Select(btnCfg_LoadTree_1));

    If(
        IsBlank(varCfg_Error),
        Notify("Node deactivated successfully.", NotificationType.Success);

        If(
            Text(varEditNodeId) = Text(varSelNodeId_L1),
            Set(varSelNodeId_L1, "");
            Set(varSelNodeId_L2, "");
            Set(varSelNodeId_L3, "");
            Select(btnCfg_RefreshSelectionContext_1)
        )
    );

    Set(varCfg_IsLoading, false)
);

If(
    IsBlank(varProjectId),

    Notify("Please select a project first.", NotificationType.Warning),

    Set(varGlobalLoading, true);
    Set(varGlobalLoadingMsg, "Loading Configuration...");
    Set(varGlobalLoadingSubMsg, "Loading report tree and scope");
    Set(varGlobalLoadingScope, "CONFIG");

    Set(varGlobalLoadAction, "LOAD_CONFIG");
    Set(varGlobalLoadPending, true)
)

// ---------------------------------------------
// 1) Validación mínima
// ---------------------------------------------
If(
    IsBlank(varTargetSubsectionId),
    Notify("Select a Level 3 subsection first.", NotificationType.Warning),

    // ---------------------------------------------
    // 2) Preparar estado del modal
    // ---------------------------------------------
    Set(varUnassignedScope, false);
    Set(varScopeModalLoading, true);

    Set(varScopeModalTargetNodeId, Text(varTargetSubsectionId));

    Set(
        varScopeModalTargetL1,
        Coalesce(
            LookUp(
                colNodes As nd,
                Text(nd.NodeId) = Text(varSelNodeId_L1),
                nd.DisplayName
            ),
            ""
        )
    );

    Set(
        varScopeModalTargetL2,
        Coalesce(
            LookUp(
                colNodes As nd,
                Text(nd.NodeId) = Text(varSelNodeId_L2),
                nd.DisplayName
            ),
            ""
        )
    );

    Set(
        varScopeModalTargetL3,
        Coalesce(
            LookUp(
                colNodes As nd,
                Text(nd.NodeId) = Text(varTargetSubsectionId),
                nd.DisplayName
            ),
            ""
        )
    );

    Set(varScopeModalMode, "assigned");
    Set(varScopeModalSearch, "");

    Clear(colScopeModalSelected);

    // ---------------------------------------------
    // 3) Reconstruir datos del modal en local
    // ---------------------------------------------
    Select(btnScopeModal_RebuildLocal);

    // ---------------------------------------------
    // 4) Abrir modal
    // ---------------------------------------------
    Set(varScopeModalOpen, true);
    Set(varScopeModalLoading, false);

    Set(varScopeModalFilterPhase, "");
    Set(varScopeModalFilterDiscipline, "");

    Reset(ddScopeModalPhase_);
    Reset(ddScopeModalDiscipline);

    Set(varScopeModalFilterSCTOnly, false);
    Reset(tglScopeModalSCT);


    Clear(colScopeModalSelected);


);

