Rules.InvariantScript:
Set(varCfg_Error, "");

If(
    varEditMode = "NEW" && varEditLevel = 2 && IsBlank(varEditParentNodeId),
    Notify("Select a header first.", NotificationType.Warning),

    varEditMode = "NEW" && varEditLevel = 3 && IsBlank(varEditParentNodeId),
    Notify("Select a section first.", NotificationType.Warning),

    varEditMode = "EDIT" && IsBlank(varEditNodeId),
    Notify("Select a node to edit.", NotificationType.Warning),

    If(
        varEditMode = "NEW",

        Set(varTmp_DisplayName, "");
        Set(varTmp_Description, "");
        Set(varTmp_SqlKey, "");
        Set(varTmp_GridKey, "");
        Set(varTmp_SortOrder, 0);
        Set(varTmp_IsActive, true);

        Set(varNodeModalOpen, true);

        Reset(txtNode_DisplayName);
        Reset(txtNode_Description);

        Reset(txtNode_SortOrder);
        Reset(tglNode_IsActive),

        With(
            {
                n: LookUp(
                    colNodes,
                    Text(NodeId) = Text(varEditNodeId)
                )
            },
            If(
                IsBlank(n.NodeId),
                Notify("Selected node not found in current tree.", NotificationType.Error),

                Set(varEditLevel, Value(n.LevelNo));
                Set(varEditParentNodeId, Text(n.ParentNodeId));

                Set(varTmp_DisplayName, Text(n.DisplayName));
                Set(varTmp_Description, Text(n.Description));
                Set(varTmp_SqlKey, Text(n.SqlKey));
                Set(varTmp_GridKey, Text(n.GridKey));
                Set(varTmp_SortOrder, Value(n.SortOrder));
                Set(varTmp_IsActive, Boolean(n.IsActive));

                Set(varNodeModalOpen, true);

                Reset(txtNode_DisplayName);
                Reset(txtNode_Description);

                Reset(txtNode_SortOrder);
                Reset(tglNode_IsActive)
            )
        )
    )
);

Set(varCfg_Error, "");

IfError(
    With(
        { r: WarRoom_ReportConfig_GetTree.Run(varProjectId) },
        ClearCollect(
            colNodes,
            ForAll(
                Table(ParseJSON(r.result)),
                {
                    NodeId: Text(Value.NodeId),
                    ProjectId: Value(Value.ProjectId),
                    LevelNo: Value(Value.LevelNo),
                    ParentNodeId: Text(Value.ParentNodeId),
                    DisplayName: Text(Value.DisplayName),
                    Description: Text(Value.Description),
                    SqlKey: Text(Value.SqlKey),
                    GridKey: Text(Value.GridKey),
                    SortOrder: Value(Value.SortOrder),
                    IsActive: Boolean(Value.IsActive)
                }
            )
        )
    ),
    Set(varCfg_Error, "Error loading report tree.")
);

If(IsBlank(varCfg_Error), Select(btnCfg_RestoreTreeSelection_1));

Set(varCfg_Error, "");

IfError(
    With(
        { r: WarRoom_ReportConfig_GetAssignments.Run(varProjectId) },
        ClearCollect(
            colAssign,
            ForAll(
                Table(ParseJSON(Coalesce(r.result, "[]"))),
                {
                    AssignmentId: Text(Value.AssignmentId),
                    ProjectId: Value(Value.ProjectId),
                    GroupKey: Text(Value.GroupKey),
                    NodeId: Text(Value.NodeId),
                    CreatedOn: Text(Value.CreatedOn),
                    CreatedBy: Text(Value.CreatedBy)
                }
            )
        )
    ),
    Set(varCfg_Error, "Error loading assignments.")
);

If(
    IsBlank(varCfg_Error),
    Select(btnCfg_BuildAssignedForTarget_1)
);

If(
    IsBlank(varCfg_Error) && varScopeModalOpen,
    Select(btnScopeModal_RebuildLocal)
);

Set(varCfg_Error, "");

IfError(
    With(
        { r: WarRoom_ReportConfig_GetScope.Run(varProjectId) },
        ClearCollect(
            colScope,
            ForAll(
                Table(ParseJSON(Coalesce(r.result, "[]"))),
                {
                    GroupKey: Text(Value.GroupKey),

                    ElementDiscipline: Text(Value.ElementDiscipline),
                    ElementLevel: Text(Value.ElementLevel),
                    PhaseName: Text(Value.PhaseName),
                    FormName: Text(Value.FormName),
                    FormDescription: Text(Value.FormDescription),

                    Sct: Boolean(Value.Sct),
                    MasterTask: Boolean(Value.MasterTask),
                    DossierTask: Boolean(Value.DossierTask),

                    TotalInspections: Value(Value.TotalInspections)
                }
            )
        )
    ),
    Set(varCfg_Error, "Error loading project scope.")
);

// =====================================================
// btnCfg_LoadAll.OnSelect
// Load Report Configuration - Multi Project Safe
// =====================================================

Set(varGlobalLoading, true);
Set(varGlobalLoadingMsg, "Loading Configuration...");
Set(varGlobalLoadingScope, "CONFIG");

If(
    IsBlank(varProjectId),
    Notify("Please select a project first.", NotificationType.Warning);
    Set(varCfg_IsLoading, false);
    Set(varLoadingMsg, "");


Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingScope, "");

    Exit()
);

If(
    varCfg_IsLoading,
    Notify("Configuration is already loading.", NotificationType.Information);

Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingScope, "");

    Exit()
);

Set(varLoadingMsg, "Loading report configuration...");
Set(varCfg_IsLoading, true);
Set(varCfg_Error, "");
Set(varConfigLoaded, false);

Clear(colNodes);
Clear(colAssign);
Clear(colScope);
Clear(colReportDictionary);
Clear(colReportMapDebug);
Clear(colAssignedForTarget);
Clear(colAssignedForTargetSummary);

// --------------------------------------------------
// 1) Tree
// --------------------------------------------------
IfError(
    Set(
        varCfg_TreeResult,
        WarRoom_ReportConfig_GetTree.Run(varProjectId).result
    ),
    Set(varCfg_Error, "Error loading report tree.");
    Notify(varCfg_Error, NotificationType.Error)
);

If(
    IsBlank(varCfg_Error),
    ClearCollect(
        colNodes,
        ForAll(
            Table(ParseJSON(Coalesce(varCfg_TreeResult, "[]"))),
            {
                NodeId: Text(Value.NodeId),
                ProjectId: Value(Value.ProjectId),
                LevelNo: Value(Value.LevelNo),
                ParentNodeId: Text(Value.ParentNodeId),
                DisplayName: Text(Value.DisplayName),
                Description: Text(Value.Description),
                SqlKey: Text(Value.SqlKey),
                GridKey: Text(Value.GridKey),
                SortOrder: Value(Value.SortOrder),
                IsActive: Boolean(Value.IsActive)
            }
        )
    )
);

// --------------------------------------------------
// 2) Assignments
// --------------------------------------------------
If(
    IsBlank(varCfg_Error),
    IfError(
        Set(
            varCfg_AssignResult,
            WarRoom_ReportConfig_GetAssignments.Run(varProjectId).result
        ),
        Set(varCfg_Error, "Error loading assignments.");
        Notify(varCfg_Error, NotificationType.Error)
    )
);

If(
    IsBlank(varCfg_Error),
    ClearCollect(
        colAssign,
        ForAll(
            Table(ParseJSON(Coalesce(varCfg_AssignResult, "[]"))),
            {
                AssignmentId: Text(Value.AssignmentId),
                ProjectId: Value(Value.ProjectId),
                GroupKey: Text(Value.GroupKey),
                NodeId: Text(Value.NodeId),
                CreatedOn: Text(Value.CreatedOn),
                CreatedBy: Text(Value.CreatedBy)
            }
        )
    )
);

// --------------------------------------------------
// 3) Scope
// --------------------------------------------------
If(
    IsBlank(varCfg_Error),
    IfError(
        Set(
            varCfg_ScopeResult,
            WarRoom_ReportConfig_GetScope.Run(varProjectId).result
        ),
        Set(varCfg_Error, "Error loading project scope.");
        Notify(varCfg_Error, NotificationType.Error)
    )
);

If(
    IsBlank(varCfg_Error),
    ClearCollect(
        colScope,
        ForAll(
            Table(ParseJSON(Coalesce(varCfg_ScopeResult, "[]"))),
            {
                GroupKey: Text(Value.GroupKey),
                ElementDiscipline: Text(Value.ElementDiscipline),
                ElementLevel: Text(Value.ElementLevel),
                PhaseName: Text(Value.PhaseName),
                FormName: Text(Value.FormName),
                FormDescription: Text(Value.FormDescription),
                Sct: Boolean(Value.Sct),
                MasterTask: Boolean(Value.MasterTask),
                TotalInspections: Value(Value.TotalInspections)
            }
        )
    )
);

// --------------------------------------------------
// 4) Report Dictionary
// --------------------------------------------------
IfError(
    With(
        {
            rDict: WarRoom_ReportDictionary_Get.Run(varProjectId)
        },
        With(
            {
                dictJson: Text(Coalesce(rDict.result, "[]"))
            },
            ClearCollect(
                colReportDictionary,
                ForAll(
                    Table(ParseJSON(dictJson)),
                    {
                        HeaderNodeId: Text(Value.HeaderNodeId),
                        Header: Text(Value.Header),
                        HeaderSort: Value(Text(Value.HeaderSort)),

                        SectionNodeId: Text(Value.SectionNodeId),
                        Section: Text(Value.Section),
                        SectionSort: Value(Text(Value.SectionSort)),

                        SubsectionNodeId: Text(Value.SubsectionNodeId),
                        Subsection: Text(Value.Subsection),
                        SubsectionSort: Value(Text(Value.SubsectionSort)),

                        SqlKey: Text(Value.SqlKey),
                        GridKey: Text(Value.GridKey),

                        Total: Value(Text(Value.Total)),
                        Done: If(
                            IsBlank(Text(Value.Done)) || Text(Value.Done) = "null",
                            Blank(),
                            Value(Text(Value.Done))
                        ),
                        Pending: If(
                            IsBlank(Text(Value.Pending)) || Text(Value.Pending) = "null",
                            Blank(),
                            Value(Text(Value.Pending))
                        )
                    }
                )
            )
        )
    ),
    Set(varCfg_Error, "Error loading report dictionary.")
);

// --------------------------------------------------
// 5) Map Debug
// --------------------------------------------------
If(
    IsBlank(varCfg_Error),
    IfError(
        Set(
            varCfg_MapResult,
            WarRoom_ReportDictionary_MapDebug.Run(varProjectId).result
        ),
        Set(varCfg_Error, "Error loading report mapping debug.");
        Notify(varCfg_Error, NotificationType.Error)
    )
);

If(
    IsBlank(varCfg_Error),
    ClearCollect(
        colReportMapDebug,
        ForAll(
            Table(ParseJSON(Coalesce(varCfg_MapResult, "[]"))),
            {
                GroupKey: Text(Value.GroupKey),
                ElementDiscipline: Text(Value.ElementDiscipline),
                ElementLevel: Text(Value.ElementLevel),
                PhaseName: Text(Value.PhaseName),
                FormName: Text(Value.FormName),
                FormDescription: Text(Value.FormDescription),
                Sct: Boolean(Value.Sct),
                MasterTask: Boolean(Value.MasterTask),
                TotalInspections: Value(Value.TotalInspections),
                Header: Text(Value.Header),
                Section: Text(Value.Section),
                Subsection: Text(Value.Subsection),
                SqlKey: Text(Value.SqlKey),
                GridKey: Text(Value.GridKey),
                SubsectionNodeId: Text(Value.SubsectionNodeId)
            }
        )
    )
);

// --------------------------------------------------
// 6) Restore selection / rebuild summary
// --------------------------------------------------
If(
    IsBlank(varCfg_Error),
    Select(btnCfg_RestoreTreeSelection_1);
    Select(btnCfg_BuildAssignedForTarget_1);
    Set(varConfigLoaded, true)
);

// --------------------------------------------------
// 7) Finish
// --------------------------------------------------
Set(varCfg_IsLoading, false);
Set(varLoadingMsg, "");

Set(varConfigLoaded, true);
Set(varGlobalLoading, false);
Set(varGlobalLoadingMsg, "");
Set(varGlobalLoadingScope, "");

Clear(colAssignedForTarget);
Clear(colAssignedForTargetSummary);

Set(varCfg_Error, "");

With(
    {
        _targetNodeId:
            Upper(
                Trim(
                    Text(
                        If(
                            varScopeModalOpen && !IsBlank(varScopeModalTargetNodeId),
                            varScopeModalTargetNodeId,
                            varTargetSubsectionId
                        )
                    )
                )
            ),

        _selL1NodeId: Upper(Trim(Text(varSelNodeId_L1))),
        _selL2NodeId: Upper(Trim(Text(varSelNodeId_L2)))
    },

    If(
        !IsBlank(_targetNodeId),

        With(
            {
                _nodeAssigns:
                    Filter(
                        colAssign,
                        ProjectId = varProjectId &&
                        Upper(Trim(Text(NodeId))) = _targetNodeId
                    )
            },

            ClearCollect(
                colAssignedForTarget,
                SortByColumns(
                    AddColumns(
                        Filter(
                            colScope As sc,
                            CountIf(_nodeAssigns, GroupKey = sc.GroupKey) > 0
                        ),

                        AssignedNodeId, _targetNodeId,

                        AssignedNodeName,
                        LookUp(
                            colNodes As nd,
                            Upper(Trim(Text(nd.NodeId))) = _targetNodeId,
                            nd.DisplayName
                        ),

                        L1Name,
                        LookUp(
                            colNodes As nd,
                            Upper(Trim(Text(nd.NodeId))) = _selL1NodeId,
                            nd.DisplayName
                        ),

                        L2Name,
                        LookUp(
                            colNodes As nd,
                            Upper(Trim(Text(nd.NodeId))) = _selL2NodeId,
                            nd.DisplayName
                        ),

                        L3Name,
                        LookUp(
                            colNodes As nd,
                            Upper(Trim(Text(nd.NodeId))) = _targetNodeId,
                            nd.DisplayName
                        )
                    ),
                    "PhaseName", SortOrder.Ascending,
                    "ElementDiscipline", SortOrder.Ascending,
                    "ElementLevel", SortOrder.Ascending,
                    "FormName", SortOrder.Ascending,
                    "FormDescription", SortOrder.Ascending
                )
            );

            ClearCollect(
                colAssignedForTargetSummary,
                FirstN(colAssignedForTarget, 4)
            )
        )
    );

    Set(
        varCfg_SelectedL1Name,
        Coalesce(
            LookUp(
                colNodes As nd,
                Upper(Trim(Text(nd.NodeId))) = _selL1NodeId,
                nd.DisplayName
            ),
            ""
        )
    );

    Set(
        varCfg_SelectedL2Name,
        Coalesce(
            LookUp(
                colNodes As nd,
                Upper(Trim(Text(nd.NodeId))) = _selL2NodeId,
                nd.DisplayName
            ),
            ""
        )
    );

    Set(
        varCfg_SelectedL3Name,
        Coalesce(
            LookUp(
                colNodes As nd,
                Upper(Trim(Text(nd.NodeId))) = _targetNodeId,
                nd.DisplayName
            ),
            ""
        )
    );

    Set(varCfg_AssignedCountForTarget, CountRows(colAssignedForTarget));

    Set(
        varCfg_ReadyForReview,
        !IsBlank(_targetNodeId) &&
        CountRows(colAssignedForTarget) > 0
    )
);

Set(varCfg_Error, "");

// ------------------------------------------------------
// 1) Cargar scope completo
// ------------------------------------------------------
IfError(
    With(
        { rScope: WarRoom_ReportConfig_GetScope.Run(varProjectId) },
        ClearCollect(
            colScope,
            ForAll(
                Table(ParseJSON(Coalesce(rScope.result, "[]"))),
                {
                    GroupKey: Text(Value.GroupKey),
                    ElementDiscipline: Text(Value.ElementDiscipline),
                    ElementLevel: Text(Value.ElementLevel),
                    PhaseName: Text(Value.PhaseName),
                    FormName: Text(Value.FormName),
                    FormDescription: Text(Value.FormDescription),
                    Sct: Boolean(Value.Sct),
                    MasterTask: Boolean(Value.MasterTask),
                    DossierTask: Boolean(Value.DossierTask),
                    TotalInspections: Value(Value.TotalInspections)
                }
            )
        )
    ),
