    With(
        { rAssign: WarRoom_ReportConfig_GetAssignments.Run(varProjectId) },
        ClearCollect(
            colAssign,
            ForAll(
                Table(ParseJSON(Coalesce(rAssign.result, "[]"))),
                {
                    AssignmentId: Text(Value.AssignmentId),
                    ProjectId: Value(Value.ProjectId),
                    GroupKey: Text(Value.GroupKey),
                    NodeId: Text(Value.NodeId),
                    CreatedOn: Text(Value.CreatedOn),
                    CreatedBy: Text(Value.CreatedBy)
                }
            )
        )
    ),
    Set(varCfg_Error, "Error loading assignments.")
);

// ------------------------------------------------------
// 3) Rebuild único
// ------------------------------------------------------
If(
    IsBlank(varCfg_Error),
    Select(btnCfg_BuildAssignedForTarget_1)
);

Set(varCfg_Error, "");

If(
    !IsBlank(varLastSavedNodeId),

    With(
        {
            n: LookUp(colNodes, Text(NodeId) = Text(varLastSavedNodeId))
        },
        If(
            !IsBlank(n.NodeId) && Value(n.LevelNo) = 1,
            Set(varSelNodeId_L1, Text(n.NodeId));
            Set(varSelNodeId_L2, "");
            Set(varSelNodeId_L3, ""),

            If(
                !IsBlank(n.NodeId) && Value(n.LevelNo) = 2,
                Set(varSelNodeId_L1, Text(n.ParentNodeId));
                Set(varSelNodeId_L2, Text(n.NodeId));
                Set(varSelNodeId_L3, ""),

                If(
                    !IsBlank(n.NodeId) && Value(n.LevelNo) = 3,
                    With(
                        {
                            n2: LookUp(colNodes, Text(NodeId) = Text(n.ParentNodeId))
                        },
                        With(
                            {
                                n1: LookUp(colNodes, Text(NodeId) = Text(n2.ParentNodeId))
                            },
                            Set(varSelNodeId_L1, Text(n1.NodeId));
                            Set(varSelNodeId_L2, Text(n2.NodeId));
                            Set(varSelNodeId_L3, Text(n.NodeId))
                        )
                    )
                )
            )
        )
    )
);


Select(btnCfg_RefreshSelectionContext_1);

Set(
    varSelectedNodeId,
    Coalesce(
        varSelNodeId_L3,
        varSelNodeId_L2,
        varSelNodeId_L1
    )
);

Set(
    varSelectedNode,
    LookUp(
        colNodes,
        Text(NodeId) = Text(varSelectedNodeId)
    )
);

Set(
    varSelectedNodeLevel,
    If(
        IsBlank(varSelectedNode.NodeId),
        0,
        Value(varSelectedNode.LevelNo)
    )
);

Set(
    varSelectedNodeName,
    Coalesce(
        varSelectedNode.DisplayName,
        ""
    )
);

Set(
    varSelectedParentName,
    Coalesce(
        LookUp(
            colNodes,
            Text(NodeId) = Text(varSelectedNode.ParentNodeId),
            DisplayName
        ),
        ""
    )
);

Set(
    varSelectedNodeIsActive,
    If(
        IsBlank(varSelectedNode.NodeId),
        false,
        Boolean(varSelectedNode.IsActive)
    )
);

Set(varTargetSubsectionId, varSelNodeId_L3);

Set(
    varTargetSubsectionName,
    If(
        IsBlank(varSelNodeId_L3),
        "",
        LookUp(
            colNodes,
            Text(NodeId) = Text(varSelNodeId_L3),
            DisplayName
        )
    )
);

// único constructor del summary
Select(btnCfg_BuildAssignedForTarget_1);

Set(varNodeModalOpen, false);

Set(varEditMode, "NEW");
Set(varEditLevel, 1);
Set(varEditParentNodeId, "");
Set(varEditNodeId, "");

Set(varTmp_DisplayName, "");
Set(varTmp_Description, "");
Set(varTmp_SqlKey, "");
Set(varTmp_GridKey, "");
Set(varTmp_SortOrder, 0);
Set(varTmp_IsActive, true);

Set(varLoadingMsg, "Saving data...");
Set(varCfg_IsLoading, true);
Set(varCfg_Error, Blank());
Set(varLastSavedNodeId, Blank());
Set(varPendingResolveSavedNode, false);
Set(varFlow_UpsertNode_Response, Blank());

With(
    {
        _nullText: "__NULL__",

        _display: Trim(txtNode_DisplayName_1.Text),
        _description: Trim(txtNode_Description_1.Text),

        _normalizedDisplay:
            Substitute(
                Substitute(
                    Substitute(
                        Substitute(
                            Substitute(
                                Lower(Trim(txtNode_DisplayName_1.Text)),
                                "á", "a"
                            ),
                            "é", "e"
                        ),
                        "í", "i"
                    ),
                    "ó", "o"
                ),
                "ú", "u"
            ),

        _normalizedNodeId:
            If(
                IsBlank(varEditNodeId),
                Blank(),
                Upper(Trim(Text(varEditNodeId)))
            ),

        _normalizedParentNodeId:
            If(
                IsBlank(varEditParentNodeId),
                Blank(),
                Upper(Trim(Text(varEditParentNodeId)))
            ),

        _sortOrder:
            If(
                IsBlank(txtNode_SortOrder_1.Value) || IsBlank(Value(txtNode_SortOrder_1.Value)),
                0,
                Value(txtNode_SortOrder_1.Value)
            )
    },

    With(
        {
            _sqlKey: Upper(Substitute(_normalizedDisplay, " ", "_")),
            _gridKey: Substitute(_normalizedDisplay, " ", "")
        },

        With(
            {
                _duplicateL3Node:
                    LookUp(
                        colNodes,
                        Upper(Text(SqlKey)) = _sqlKey &&
                        Upper(Text(ParentNodeId)) = Upper(Text(varEditParentNodeId)) &&
                        Upper(Text(NodeId)) <> Upper(Text(varEditNodeId))
                    )
            },

            With(
                {
                    _validationMessage:
                        If(
                            IsBlank(_display),
                            "DisplayName is required.",

                            varEditLevel in [2, 3] && IsBlank(varEditParentNodeId),
                            "ParentNodeId missing before save.",

                            varEditLevel = 3 && !IsBlank(_duplicateL3Node.NodeId),
                            "Duplicate key generated. Change DisplayName.",

                            Blank()
                        )
                },

                If(
                    !IsBlank(_validationMessage),

                    Set(varCfg_Error, _validationMessage);
                    Notify(_validationMessage, NotificationType.Error);
                    Set(varCfg_IsLoading, false),

                    Set(varLastSavedLevel, Value(varEditLevel));
                    Set(varLastSavedParentNodeId, _normalizedParentNodeId);
                    Set(varLastSavedDisplayName, _display);
                    Set(varLastSavedSqlKey, If(varEditLevel = 3, _sqlKey, ""));
                    Set(varLastSavedGridKey, If(varEditLevel = 3, _gridKey, ""));

                    If(
                        !IsBlank(varEditNodeId),
                        Set(varLastSavedNodeId, _normalizedNodeId),
                        Set(varPendingResolveSavedNode, true)
                    );

                    Set(varCfg_SaveStartedOn, Now());

                    With(
                        {
                            _flowDisplayName: If(IsBlank(_display), _nullText, _display),
                            _flowDescription: If(IsBlank(_description), _nullText, _description),
                            _flowSqlKey: If(varEditLevel = 3 && !IsBlank(_sqlKey), _sqlKey, _nullText),
                            _flowGridKey: If(varEditLevel = 3 && !IsBlank(_gridKey), _gridKey, _nullText),
                            _flowUserName: If(IsBlank(User().Email), _nullText, User().Email),
                            _flowNodeId: If(IsBlank(_normalizedNodeId), _nullText, _normalizedNodeId),
                            _flowParentNodeId: If(IsBlank(_normalizedParentNodeId), _nullText, _normalizedParentNodeId),
                            _flowIsActive: tglNode_IsActive_1.Value
                        },


                        IfError(
                            Set(
                                varFlow_UpsertNode_Response,
                                WarRoom_ReportConfig_UpsertNode.Run(
                                    varProjectId,
                                    varEditLevel,
                                    _flowDisplayName,
                                    _flowDescription,
                                    _flowSqlKey,
                                    _flowGridKey,
                                    _sortOrder,
                                    _flowIsActive,
                                    _flowUserName,
                                    _flowNodeId,
                                    _flowParentNodeId
                                )
                            ),
                            Set(varCfg_Error, FirstError.Message);
                            Notify(
                                "Error saving node: " & FirstError.Message,
                                NotificationType.Error
                            )
                        )
                    );

                    Set(varCfg_SaveFinishedOn, Now());

                    If(
                        IsBlank(varCfg_Error),
                        Notify("Flow called successfully.", NotificationType.Information)
                    );

                    If(
                        IsBlank(varCfg_Error),
                        Select(btnCfg_LoadTree_1)
                    );

                    If(
                        IsBlank(varCfg_Error),
                        Notify("Node saved successfully.", NotificationType.Success);

                        Set(varNodeModalOpen, false);

                        Set(varEditMode, "NEW");
                        Set(varEditLevel, 1);
                        Set(varEditParentNodeId, Blank());
                        Set(varEditNodeId, Blank());

                        Set(varTmp_DisplayName, Blank());
                        Set(varTmp_Description, Blank());
                        Set(varTmp_SqlKey, Blank());
                        Set(varTmp_GridKey, Blank());
                        Set(varTmp_SortOrder, 0);
                        Set(varTmp_IsActive, true),

                        Notify(varCfg_Error, NotificationType.Error)
                    );

                    Set(varCfg_IsLoading, false)
                )
            )
        )
    )
);

